sealed interface CalculatorState {
    val display: String

    data class Entering(override val display: String) : CalculatorState

    data class Accumulating(
        val accumulator: Double,
        val operator: Operator,
        override val display: String,
        val typing: Boolean = false,
    ) : CalculatorState

    fun withEntry(text: String): CalculatorState = when (val current = this) {
        is Entering -> Entering(text)
        is Accumulating -> current.copy(display = text, typing = true)
    }
}

class CalculatorEngine {
    private val zero = "0"

    var state: CalculatorState = CalculatorState.Entering(zero)
        private set

    val display: String get() = state.display

    fun clear() {
        state = CalculatorState.Entering(zero)
    }
}

private val errorDisplay = "Error"

private fun combine(operator: Operator, left: Double, right: Double): Double? =
    when (operator) {
        Operator.ADD -> left + right
        Operator.SUBTRACT -> left - right
        Operator.MULTIPLY -> left * right
        Operator.DIVIDE -> if (right == 0.0) null else left / right
    }

private val maxEntryLength = 12

private fun isFreshEntry(text: String): Boolean =
    text == zero || text == errorDisplay

fun digit(value: Int) {
    val current = state
    val replaces = isFreshEntry(current.display) ||
        (current is CalculatorState.Accumulating && !current.typing)
    val next = if (replaces) value.toString() else current.display + value
    if (next.length <= maxEntryLength) {
        state = state.withEntry(next)
    }
}

fun decimalPoint() {
    val current = display
    if (isFreshEntry(current)) {
        state = state.withEntry("$zero.")
    } else if (!current.contains('.')) {
        state = state.withEntry("$current.")
    }
}

fun toggleSign() {
    val current = display
    state = state.withEntry(
        when {
            current.startsWith("-") -> current.removePrefix("-")
            isFreshEntry(current) -> current
            else -> "-$current"
        },
    )
}

fun percent() {
    val value = when (val current = state) {
        is CalculatorState.Entering -> currentValue() / 100
        is CalculatorState.Accumulating ->
            if (current.typing) {
                current.accumulator * currentValue() / 100
            } else {
                current.accumulator / 100
            }
    }
    state = state.withEntry(format(value))
}

private fun currentValue(): Double = display.toDoubleOrNull() ?: 0.0

fun operator(next: Operator) {
    state = when (val current = state) {
        is CalculatorState.Entering -> {
            val value = currentValue()
            CalculatorState.Accumulating(value, next, format(value))
        }
        is CalculatorState.Accumulating ->
            combine(current.operator, current.accumulator, currentValue())
                ?.let { CalculatorState.Accumulating(it, next, format(it)) }
                ?: CalculatorState.Entering(errorDisplay)
    }
}

fun equals() {
    state = when (val current = state) {
        is CalculatorState.Entering -> current
        is CalculatorState.Accumulating ->
            combine(current.operator, current.accumulator, currentValue())
                ?.let { CalculatorState.Entering(format(it)) }
                ?: CalculatorState.Entering(errorDisplay)
    }
}

package com.example.calculator

import org.junit.Assert.assertEquals
import org.junit.Test

class CalculatorEngineTest {
    private fun CalculatorEngine.presses(vararg keys: String): CalculatorEngine {
        for (key in keys) {
            if (key == "+/-") {
                toggleSign()
                continue
            }
            for (char in key) {
                when (char) {
                    '.' -> decimalPoint()
                    '=' -> equals()
                    '%' -> percent()
                    '+' -> operator(Operator.ADD)
                    '-' -> operator(Operator.SUBTRACT)
                    '*' -> operator(Operator.MULTIPLY)
                    '/' -> operator(Operator.DIVIDE)
                    else -> digit(char.digitToInt())
                }
            }
        }
        return this
    }

    @Test
    fun typingADigitReplacesTheInitialZero() {
        assertEquals("0", CalculatorEngine().display)
        assertEquals("7", CalculatorEngine().presses("7").display)
        assertEquals("75", CalculatorEngine().presses("7", "5").display)
    }

    @Test
    fun clearReturnsToZero() {
        val engine = CalculatorEngine().presses("7", "+", "9")
        engine.clear()
        assertEquals("0", engine.display)
    }
}

@Test
fun everyOperatorCombinesTheAccumulatorWithTheEntry() {
    assertEquals("7", CalculatorEngine().presses("3", "+", "4", "=").display)
    assertEquals("-1", CalculatorEngine().presses("3", "-", "4", "=").display)
    assertEquals("12", CalculatorEngine().presses("3", "*", "4", "=").display)
    assertEquals("0.75", CalculatorEngine().presses("3", "/", "4", "=").display)
}

@Test
fun pressingAnotherOperatorAppliesThePendingOne() {
    assertEquals("25", CalculatorEngine().presses("3", "+", "2", "*", "=").display)
}

@Test
fun dividingByZeroShowsAnError() {
    assertEquals("Error", CalculatorEngine().presses("8", "/", "0", "=").display)
    assertEquals("5", CalculatorEngine().presses("8", "/", "0", "=", "5").display)
}

@Test
fun theEntryStopsGrowingAtTwelveCharacters() {
    assertEquals("123456789012", CalculatorEngine().presses("1234567890123").display)
}

@Test
fun onlyOneDecimalPointPerEntry() {
    assertEquals("1.5", CalculatorEngine().presses("1", ".", "5", ".").display)
    assertEquals("1.52", CalculatorEngine().presses("1", ".", "5", ".", "2").display)
}

@Test
fun percentIsTakenFromTheAccumulator() {
    assertEquals("2", CalculatorEngine().presses("2", "0", "0", "+", "%").display)
    assertEquals(
        "220",
        CalculatorEngine().presses("2", "0", "0", "+", "1", "0", "%", "=").display,
    )
}

@Test
fun percentHalvesAStandaloneEntry() {
    assertEquals("0.05", CalculatorEngine().presses("5", "%").display)
}

@Test
fun theDecimalPointStartsFromAZero() {
    assertEquals("0.", CalculatorEngine().presses(".").display)
}

@Test
fun toggleSignSkipsAFreshZero() {
    assertEquals("-5", CalculatorEngine().presses("5", "+/-").display)
    assertEquals("5", CalculatorEngine().presses("5", "+/-", "+/-").display)
    assertEquals("0", CalculatorEngine().presses("+/-").display)
}

