import androidx.lifecycle.ViewModel
import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.flow.StateFlow
import kotlinx.coroutines.flow.asStateFlow
import kotlinx.coroutines.flow.update

data class CalculatorUiState(val display: String = "0")

class CalculatorViewModel : ViewModel() {
    private val engine = CalculatorEngine()

    private val _uiState = MutableStateFlow(CalculatorUiState())
    val uiState: StateFlow<CalculatorUiState> = _uiState.asStateFlow()

    fun onDigit(digit: Int) = press { engine.digit(digit) }

    fun onDecimalPoint() = press(engine::decimalPoint)

    fun onToggleSign() = press(engine::toggleSign)

    fun onPercent() = press(engine::percent)

    fun onOperator(operator: Operator) = press { engine.operator(operator) }

    fun onEquals() = press(engine::equals)

    fun onClear() = press(engine::clear)

    private fun press(action: () -> Unit) {
        action()
        _uiState.update { CalculatorUiState(display = engine.display) }
    }
}

